//! RayX's design tokens as NSH theme types: the structs of `theme.*` and `platform.*`, their
//! values in every mode, the mode enums and the role sets.
//!
//! Generated by `theme_codegen.py` (the `rayx-components` skill in RayX.Root) from the DTCG
//! export in `RayX.Design/tokens/dtcg`. Do not edit: change the tokens in Figma, export them,
//! then run `python .claude/skills/rayx-components/scripts/theme_codegen.py write` from RayX.Root.

#![allow(clippy::excessive_precision, clippy::unreadable_literal)]

use nsh_core::color::rgba;
use nsh_core::geometry::px;
use nsh_core::prelude::*;

/// The accent: the hue of the theme colors (Figma's `Theme.Colors` mode).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, PropEnum)]
pub enum Accent {
    /// `cyan`.
    #[default]
    Cyan,
    /// `sky`.
    Sky,
    /// `blue`.
    Blue,
}

impl Accent {
    /// Every accent mode, in the design system's order.
    pub const ALL: [Accent; 3] = [Accent::Cyan, Accent::Sky, Accent::Blue];

    /// Its name in the token export and in TSX.
    pub const fn name(self) -> &'static str {
        match self {
            Accent::Cyan => "cyan",
            Accent::Sky => "sky",
            Accent::Blue => "blue",
        }
    }
}

/// The density: the sizes of every level and scale (Figma's `Platform.Density` mode).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, PropEnum)]
pub enum Density {
    /// `desktop`.
    #[default]
    Desktop,
    /// `touch`.
    Touch,
}

impl Density {
    /// Every density mode, in the design system's order.
    pub const ALL: [Density; 2] = [Density::Desktop, Density::Touch];

    /// Its name in the token export and in TSX.
    pub const fn name(self) -> &'static str {
        match self {
            Density::Desktop => "desktop",
            Density::Touch => "touch",
        }
    }
}

/// The operating system whose window chrome the app draws (Figma's `Platform.OS` mode).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, PropEnum)]
pub enum Os {
    /// `windows`.
    #[default]
    Windows,
    /// `macos`.
    Macos,
    /// `gnome`.
    Gnome,
    /// `kde`.
    Kde,
}

impl Os {
    /// Every os mode, in the design system's order.
    pub const ALL: [Os; 4] = [Os::Windows, Os::Macos, Os::Gnome, Os::Kde];

    /// Its name in the token export and in TSX.
    pub const fn name(self) -> &'static str {
        match self {
            Os::Windows => "windows",
            Os::Macos => "macos",
            Os::Gnome => "gnome",
            Os::Kde => "kde",
        }
    }
}

/// `theme.colors.surfaces`: backgrounds, and the text, borders and links drawn on them.
#[derive(Debug, Clone, PartialEq, AppTheme)]
pub struct Surfaces {
    /// Background of the whole application window; the bottom layer every other surface sits on.
    /// Aliases the surface set the current theme mode selects.
    #[token(color)]
    pub app: AdaptiveColor,
    /// Background of panels laid directly on `surfaces/app` (sidebars, cards, toolbars); first
    /// layer of the surface stack. Aliases the surface set the current theme mode selects.
    #[token(color)]
    pub panel1: AdaptiveColor,
    /// Hover background for an element resting on `surfaces/panel1`. Panels rarely have a hover
    /// state; use only when a panel-colored element is interactive. Aliases the surface set the
    /// current theme mode selects.
    #[token(color)]
    pub panel1_hover: AdaptiveColor,
    /// Selected background for an element resting on `surfaces/panel1`. Panels rarely have a
    /// selected state; use only when a panel-colored element can be selected. Aliases the surface
    /// set the current theme mode selects.
    #[token(color)]
    pub panel1_selected: AdaptiveColor,
    /// Background of panels nested inside `surfaces/panel1` (or placed directly on `surfaces/app`);
    /// second layer of the surface stack. Aliases the surface set the current theme mode selects.
    #[token(color)]
    pub panel2: AdaptiveColor,
    /// Hover background for an element resting on `surfaces/panel2`. Panels rarely have a hover
    /// state; use only when a panel-colored element is interactive. Aliases the surface set the
    /// current theme mode selects.
    #[token(color)]
    pub panel2_hover: AdaptiveColor,
    /// Selected background for an element resting on `surfaces/panel2`. Panels rarely have a
    /// selected state; use only when a panel-colored element can be selected. Aliases the surface
    /// set the current theme mode selects.
    #[token(color)]
    pub panel2_selected: AdaptiveColor,
    /// Background of elements floating above the whole app: dialogs, popovers, menus, tooltips,
    /// notifications. Aliases the surface set the current theme mode selects.
    #[token(color)]
    pub overlay: AdaptiveColor,
    /// Main text color on every surface of the set. Meets WCAG AAA against `surfaces/app`,
    /// `surfaces/panel1`, `surfaces/panel2` and `surfaces/overlay`. Monochrome icons use it too (or
    /// `textMuted` when they should be muted). Aliases the surface set the current theme mode
    /// selects.
    #[token(color)]
    pub text: AdaptiveColor,
    /// Secondary, muted text color on every surface of the set. Meets WCAG AAA where possible and
    /// at least WCAG AA. Monochrome icons use it when they should recede. Aliases the surface set
    /// the current theme mode selects.
    #[token(color)]
    pub text_muted: AdaptiveColor,
    /// Faintest text color over `bg`, `bgHover` and `bgSelected`: placeholders, hints and captions.
    /// Roughly 3 to 4:1 contrast, below WCAG AA in some roles, so never use it for essential text.
    /// Aliases the role set the current theme mode selects.
    #[token(color)]
    pub text_subtle: AdaptiveColor,
    /// Background of every second row in tables, lists, trees and property grids. Translucent, so
    /// it works on any surface (panel1, panel2, overlay); the row itself has no background. Hover
    /// and selected rows use the neutral element backgrounds.
    #[token(color)]
    pub alternate_row_bg: AdaptiveColor,
    /// Text color of inline links and link-style buttons at rest.
    #[token(color)]
    pub link: AdaptiveColor,
    /// Text color of links while hovered.
    #[token(color)]
    pub link_hover: AdaptiveColor,
    /// Main border color of components, on any surface or fill: inputs, outlined buttons, toggles,
    /// checkboxes and radios. Translucent black (light) / white (dark), so it composites onto
    /// whichever background it sits on, colored fills included.
    #[token(color)]
    pub border: AdaptiveColor,
    /// Muted border color for surfaces and dividers: panels, overlays, cards, tables, separators,
    /// the window edge and outlines that should recede. Translucent black (light) / white (dark),
    /// so it composites onto whichever background it sits on.
    #[token(color)]
    pub border_muted: AdaptiveColor,
    /// Danger text and icons drawn directly on a surface: destructive menu items, field error
    /// messages, negative values. At least WCAG AA (5.9:1 Light, 8:1 Dark) against `surfaces/app`,
    /// `surfaces/panel1`, `surfaces/panel2` and `surfaces/overlay`. Text on a danger fill uses
    /// `roles/danger/text`. The same in every accent.
    #[token(color)]
    pub text_danger: AdaptiveColor,
    /// Success text and icons drawn directly on a surface: positive values, success messages,
    /// valid-field hints. At least WCAG AA (4.6:1 Light, 10:1 Dark) against `surfaces/app`,
    /// `surfaces/panel1`, `surfaces/panel2` and `surfaces/overlay`. Text on a success fill uses
    /// `roles/success/text`. The same in every accent.
    #[token(color)]
    pub text_success: AdaptiveColor,
    /// Backdrop behind modal overlays (Dialog, AlertDialog, Sheet): a translucent black layer
    /// between the app and the overlay that dims the content below. The same in every accent.
    #[token(color)]
    pub scrim: AdaptiveColor,
    /// Informational text and icons drawn directly on a surface: outlined info tags, notes, hints
    /// that carry information. At least WCAG AA (6.2:1 Light, 8.4:1 Dark) against `surfaces/app`,
    /// `surfaces/panel1`, `surfaces/panel2` and `surfaces/overlay`. Text on an info fill uses
    /// `roles/alerts/info/text`. The same in every accent.
    #[token(color)]
    pub text_info: AdaptiveColor,
    /// Warning text and icons drawn directly on a surface: outlined warning tags, cautions, values
    /// near a limit. At least WCAG AA (4.6:1 Light, 10.5:1 Dark) against `surfaces/app`,
    /// `surfaces/panel1`, `surfaces/panel2` and `surfaces/overlay`. Text on a warning fill uses
    /// `roles/alerts/warning/text`. The same in every accent.
    #[token(color)]
    pub text_warning: AdaptiveColor,
    /// Text and icons drawn over pictures and video, such as the Video control bar on
    /// `surfaces/scrim`: white in both color modes, because the media below stays the same in Light
    /// and Dark. The same in every accent.
    #[token(color)]
    pub on_media: AdaptiveColor,
}

/// `theme.colors.roles.neutral`: the neutral role's colors, with `bg_strong` for tracks and
/// placeholders.
#[derive(Debug, Clone, PartialEq, AppTheme)]
pub struct NeutralRole {
    /// Resting background of the element (button, tab, chip, alert, and similar). Neutral role:
    /// default components without semantic meaning (secondary buttons, tabs, inputs, list items).
    /// Aliases the role set the current theme mode selects.
    #[token(color)]
    pub bg: AdaptiveColor,
    /// Strongest neutral background, laid over the element's own surface: tracks (switch, slider,
    /// group box), indicators (carousel, stepper), skeletons and placeholders, avatars and tags.
    /// Next step after bgSelected.
    #[token(color)]
    pub bg_strong: AdaptiveColor,
    /// Translucent tint of the role color for soft elements that let the surface behind show
    /// through: inactive badges, soft tags and chips, the hover of transparent elements. Lighter
    /// than `bg`. Neutral role: default components without semantic meaning (secondary buttons,
    /// tabs, inputs, list items). Aliases the role set the current theme mode selects.
    #[token(color)]
    pub bg_translucent: AdaptiveColor,
    /// Background of the element while the pointer hovers over it. Neutral role: default components
    /// without semantic meaning (secondary buttons, tabs, inputs, list items). Aliases the role set
    /// the current theme mode selects.
    #[token(color)]
    pub bg_hover: AdaptiveColor,
    /// Background of the element when selected or toggled on. Neutral role: default components
    /// without semantic meaning (secondary buttons, tabs, inputs, list items). Aliases the role set
    /// the current theme mode selects.
    #[token(color)]
    pub bg_selected: AdaptiveColor,
    /// Background of the element while the pointer hovers over it when selected or toggled on.
    /// Neutral role: default components without semantic meaning (secondary buttons, tabs, inputs,
    /// list items). Aliases the role set the current theme mode selects.
    #[token(color)]
    pub bg_selected_hover: AdaptiveColor,
    /// Main text color over `bg`, `bgHover` and `bgSelected`. At least WCAG AA (4.5:1) against
    /// them, AAA where the fill allows. Neutral role: default components without semantic meaning
    /// (secondary buttons, tabs, inputs, list items). Aliases the role set the current theme mode
    /// selects.
    #[token(color)]
    pub text: AdaptiveColor,
    /// Secondary, muted text color over `bg`, `bgHover` and `bgSelected`. At least WCAG AA against
    /// them. Neutral role: default components without semantic meaning (secondary buttons, tabs,
    /// inputs, list items). Aliases the role set the current theme mode selects.
    #[token(color)]
    pub text_muted: AdaptiveColor,
    /// Faintest text color over `bg`, `bgHover` and `bgSelected`: placeholders, hints and captions.
    /// Roughly 3 to 4:1 contrast, below WCAG AA in some roles, so never use it for essential text.
    /// Aliases the role set the current theme mode selects.
    #[token(color)]
    pub text_subtle: AdaptiveColor,
    /// Accent color for icons and small emphasized marks inside the element (e.g. the icon of an
    /// alert). Deliberately lighter than `text`, which reads better perceptually. Neutral role:
    /// default components without semantic meaning (secondary buttons, tabs, inputs, list items).
    /// Aliases the role set the current theme mode selects.
    #[token(color)]
    pub accent: AdaptiveColor,
    /// Background of the element while it is pressed (the press in progress). Neutral role: default
    /// components without semantic meaning (secondary buttons, tabs, inputs, list items). Aliases
    /// the role set the current theme mode selects.
    #[token(color)]
    pub bg_active: AdaptiveColor,
}

