/// `theme.colors.interaction`: state cues (disabled, focus rings, drag and drop, the caret, text
/// selection).
#[derive(Debug, Clone, PartialEq, AppTheme)]
pub struct Interaction {
    /// Background of a disabled component, laid over the element's own surface: a muted gray veil
    /// that darkens in light mode and lightens in dark mode. Also used when the disabled component
    /// is selected or toggled on.
    #[token(color)]
    pub disabled_bg: AdaptiveColor,
    /// Text and icon color of a disabled component, laid over the element's own surface: readable
    /// but clearly inactive, darkening in light mode and lightening in dark mode. Also used when
    /// the disabled component is selected or toggled on.
    #[token(color)]
    pub disabled_fg: AdaptiveColor,
    /// Border of a disabled component, laid over the element's own surface: a gray edge one step
    /// stronger than `disabledBg`, darkening in light mode and lightening in dark mode. Also used
    /// when the disabled component is selected or toggled on.
    #[token(color)]
    pub disabled_border: AdaptiveColor,
    /// Focus ring drawn around the keyboard-focused component (buttons, inputs, checkboxes, list
    /// items). Follows the theme accent.
    #[token(color)]
    pub focus_ring: AdaptiveColor,
    /// Focus ring drawn around a keyboard-focused danger component (danger buttons, invalid
    /// fields). The same in every accent.
    #[token(color)]
    pub focus_ring_danger: AdaptiveColor,
    /// Focus ring drawn around a keyboard-focused success component (success buttons, valid
    /// fields). The same in every accent.
    #[token(color)]
    pub focus_ring_success: AdaptiveColor,
    /// Border or outline of an element while it is being dragged (data table columns, dock panels,
    /// property grid rows).
    #[token(color)]
    pub drag_border: AdaptiveColor,
    /// Highlight fill of a valid drop target while something is dragged over it (dock zones,
    /// lists). Uses the translucent tint of the current accent.
    #[token(color)]
    pub drop_target: AdaptiveColor,
    /// Blinking text cursor in editable fields (inputs, number fields, OTP fields, text areas, code
    /// editor).
    #[token(color)]
    pub caret: AdaptiveColor,
    /// Text color of selected text inside editable fields; sits on `textSelectionBg`.
    #[token(color)]
    pub text_selection_fg: AdaptiveColor,
    /// Highlight behind selected text inside editable fields. Follows the theme accent.
    #[token(color)]
    pub text_selection_bg: AdaptiveColor,
}

