impl ColorTokens {
    /// The tokens of `theme.colors` in `accent`.
    pub fn of(accent: Accent) -> Self {
        match accent {
            Accent::Cyan => make_colors_cyan(),
            Accent::Sky => make_colors_sky(),
            Accent::Blue => make_colors_blue(),
        }
    }
}

impl EffectTokens {
    /// The tokens of `theme.effects` in `accent`.
    pub fn of(accent: Accent) -> Self {
        match accent {
            Accent::Cyan => make_effects(),
            Accent::Sky => make_effects(),
            Accent::Blue => make_effects(),
        }
    }
}

impl DensityTokens {
    /// The tokens of `platform.density` in `density`.
    pub fn of(density: Density) -> Self {
        match density {
            Density::Desktop => make_density_desktop(),
            Density::Touch => make_density_touch(),
        }
    }
}

impl OsTokens {
    /// The tokens of `platform.os` in `os`.
    pub fn of(os: Os) -> Self {
        match os {
            Os::Windows => make_os(),
            Os::Macos => make_os(),
            Os::Gnome => make_os(),
            Os::Kde => make_os(),
        }
    }
}

impl ThemeTokens {
    /// The colors and effects of `accent`, each color in Light and Dark.
    pub fn of(accent: Accent) -> Self {
        ThemeTokens {
            colors: ColorTokens::of(accent),
            effects: EffectTokens::of(accent),
        }
    }
}

impl PlatformTokens {
    /// The sizes of `density` and the window chrome of `os`.
    pub fn of(density: Density, os: Os) -> Self {
        PlatformTokens {
            density: DensityTokens::of(density),
            os: OsTokens::of(os),
        }
    }
}

