/// RayX's role sets: the colors a role takes from one hue, in Light and Dark. The theme's roles
/// alias them (the accent picks primary's); `RoleColors::set` gives one to a custom theme.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PropEnum)]
pub enum RoleSet {
    /// The `blue` set.
    Blue,
    /// The `sky` set.
    Sky,
    /// The `cyan` set.
    Cyan,
    /// The `red` set.
    Red,
    /// The `green` set.
    Green,
}

impl RoleSet {
    /// Every role set.
    pub const ALL: [RoleSet; 5] = [
        RoleSet::Blue,
        RoleSet::Sky,
        RoleSet::Cyan,
        RoleSet::Red,
        RoleSet::Green,
    ];
}

impl RoleColors {
    /// The colors of role set `set`, in Light and Dark.
    pub fn set(set: RoleSet) -> Self {
        match set {
            RoleSet::Blue => RoleColors {
                bg: c(0x0052c1ff, 0x0053bbff),
                bg_translucent: c(0x006af824, 0x376bff8a),
                bg_hover: c(0x0052c1e6, 0x0053bbe6),
                bg_selected: c(0x0043a2ff, 0x003a85ff),
                bg_selected_hover: c(0x0043a2e6, 0x003a85e6),
                text: c(0xffffffff, 0xffffffff),
                text_muted: c(0xd3e1f7ff, 0xd3e0f5ff),
                text_subtle: c(0xa7c3efff, 0xa7c1ebff),
                accent: c(0xb4d1ffff, 0xb2d0ffff),
                bg_active: c(0x0052c1cc, 0x0053bbcc),
            },
            RoleSet::Sky => RoleColors {
                bg: c(0x075e8eff, 0x055d8dff),
                bg_translucent: c(0x0094f71f, 0x1cacff6e),
                bg_hover: c(0x075e8ee6, 0x055d8de6),
                bg_selected: c(0x085079ff, 0x004368ff),
                bg_selected_hover: c(0x085079e6, 0x004368e6),
                text: c(0xffffffff, 0xffffffff),
                text_muted: c(0xcde3f5ff, 0xcee2f3ff),
                text_subtle: c(0x9bc8ebff, 0x9dc5e7ff),
                accent: c(0xa6d6fbff, 0xa5d5fbff),
                bg_active: c(0x075e8ecc, 0x055d8dcc),
            },
            RoleSet::Cyan => RoleColors {
                bg: c(0x007796ff, 0x007796ff),
                bg_translucent: c(0x00e4fa30, 0x39c9ff63),
                bg_hover: c(0x007796e6, 0x007796e6),
                bg_selected: c(0x006079ff, 0x006079ff),
                bg_selected_hover: c(0x006079e6, 0x006079e6),
                text: c(0xffffffff, 0xffffffff),
                text_muted: c(0xdcf4feff, 0xdcf4feff),
                text_subtle: c(0xbaeafeff, 0xbaeafeff),
                accent: c(0x96ddf8ff, 0x96ddf8ff),
                bg_active: c(0x007796cc, 0x007796cc),
            },
            RoleSet::Red => RoleColors {
                bg: c(0xe7000bff, 0xff646799),
                bg_translucent: c(0xf600001d, 0xff3a3a7f),
                bg_hover: c(0xe7000be6, 0xff64678a),
                bg_selected: c(0x99000cff, 0x9a000dff),
                bg_selected_hover: c(0x99000ce6, 0x9a000de6),
                text: c(0xffffffff, 0xffffffff),
                text_muted: c(0xf8d8d4ff, 0xf8d8d4ff),
                text_subtle: c(0xf1b1a9ff, 0xf1b1a9ff),
                accent: c(0xffc3bbff, 0xffc3bbff),
                bg_active: c(0xe7000bcc, 0xff64677a),
            },
            RoleSet::Green => RoleColors {
                bg: c(0x00662cff, 0x00672dff),
                bg_translucent: c(0x00e95023, 0x3dff8a53),
                bg_hover: c(0x00662ce6, 0x00672de6),
                bg_selected: c(0x005524ff, 0x005625ff),
                bg_selected_hover: c(0x005524e6, 0x005625e6),
                text: c(0xffffffff, 0xffffffff),
                text_muted: c(0xd4e2d7ff, 0xd4e3d7ff),
                text_subtle: c(0xa9c5afff, 0xa9c7afff),
                accent: c(0x8ce09fff, 0x8de1a0ff),
                bg_active: c(0x00662ccc, 0x00672dcc),
            },
        }
    }
}

/// `0xRRGGBBAA` in Light and in Dark.
fn c(light: u32, dark: u32) -> AdaptiveColor {
    AdaptiveColor::new(rgba(light), rgba(dark))
}

/// One shadow layer: offsets, blur and spread in points, its color `0xRRGGBBAA`.
fn layer(offset_x: f32, offset_y: f32, blur: f32, spread: f32, color: u32) -> BoxShadow {
    BoxShadow {
        offset_x: px(offset_x),
        offset_y: px(offset_y),
        blur: px(blur),
        spread: px(spread),
        color: rgba(color).into(),
        inset: false,
    }
}
